// Broadsheet drawing sheet: author the Arch D title block family from a resolved
// sheet.<property>.json (generated by packages/ui-kit/scripts/gen-sheet.mjs).
//
//   bim revit exec --pid <P> --allow-no-doc --no-transaction --file revit/titleblock.cs \
//       --args-json '{"layout":"<dir>/sheet.bimcli.json","out":"<dir>/out"}'
//
// The family holds the frame and the STATIC words only (wordmark, URL, tagline,
// field labels, disclaimer). Revit's API cannot create parameter-bound labels in a
// family, so every per-sheet value is written onto the sheet by fill_sheet.cs, into
// the boxes the layout defines. Touches no project document.
using System.IO;
using System.Text.Json;

string layoutPath = args != null && args.ContainsKey("layout") && args["layout"] != null ? args["layout"].ToString() : "";
string outDir = args != null && args.ContainsKey("out") && args["out"] != null ? args["out"].ToString() : "";
if (layoutPath == "" || outDir == "") return new { ok = false, error = "args.layout and args.out are required" };
var L = JsonDocument.Parse(File.ReadAllText(layoutPath)).RootElement;

string rftName = L.GetProperty("sheet").GetProperty("family_template").GetString();
string rft = Path.Combine(@"C:\ProgramData\Autodesk\RVT " + app.VersionNumber + @"\Family Templates\English-Imperial\Titleblocks", rftName);
string family = L.GetProperty("family").GetString();
string prefix = L.GetProperty("type_prefix").GetString();
Directory.CreateDirectory(outDir);
string rfa = Path.Combine(outDir, family + ".rfa");
if (!File.Exists(rft)) return new { ok = false, stage = "template", rft };

double W = L.GetProperty("sheet").GetProperty("size_in")[0].GetDouble();
double H = L.GetProperty("sheet").GetProperty("size_in")[1].GetDouble();
double b = L.GetProperty("border_in").GetDouble();
var S = L.GetProperty("strip");
double x0 = S.GetProperty("x0").GetDouble(), x1 = S.GetProperty("x1").GetDouble(), pad = S.GetProperty("pad").GetDouble();
Func<double, double> FT = i => i / 12.0;   // inches -> feet

var rows = new Dictionary<string, JsonElement>();
foreach (var r in L.GetProperty("rows").EnumerateArray()) rows[r.GetProperty("id").GetString()] = r;

int curves = 0, texts = 0;
var styleIds = new Dictionary<string, ElementId>();
string err = null;
Document f = null;
try {
    f = app.NewFamilyDocument(rft);
    // ActiveView is null on a new family document: collect the drafting view.
    var view = new FilteredElementCollector(f).OfClass(typeof(View)).Cast<View>()
        .FirstOrDefault(v => !v.IsTemplate && v.ViewType == ViewType.DraftingView)
        ?? new FilteredElementCollector(f).OfClass(typeof(View)).Cast<View>().FirstOrDefault(v => !v.IsTemplate);
    if (view == null) { f.Close(false); return new { ok = false, stage = "view" }; }

    using (var t = new Transaction(f, "Broadsheet title block")) {
        t.Start();

        // The stock template ships its own border lines; drop them so ours is the only frame.
        foreach (var id in new FilteredElementCollector(f, view.Id).OfClass(typeof(CurveElement)).ToElementIds().ToList()) {
            try { f.Delete(id); } catch { }
        }

        var gs = new FilteredElementCollector(f).OfClass(typeof(GraphicsStyle)).Cast<GraphicsStyle>().ToList();
        Func<string, GraphicsStyle> lineStyle = n => gs.FirstOrDefault(g => g.Name == n);
        Action<double, double, double, double, string> line = (ax, ay, bx, by, style) => {
            var dc = f.FamilyCreate.NewDetailCurve(view, Line.CreateBound(new XYZ(FT(ax), FT(ay), 0), new XYZ(FT(bx), FT(by), 0)));
            var st = lineStyle(style); if (st != null) dc.LineStyle = st;
            curves++;
        };

        // frame: sheet border + the strip's left edge; hairline row rules inside the strip
        line(b, b, W - b, b, "Medium Lines");
        line(W - b, b, W - b, H - b, "Medium Lines");
        line(W - b, H - b, b, H - b, "Medium Lines");
        line(b, H - b, b, b, "Medium Lines");
        line(x0, b, x0, H - b, "Medium Lines");
        foreach (var r in rows.Values) {
            double y0 = r.GetProperty("y0").GetDouble();
            if (y0 > b + 0.01) line(x0, y0, x1, y0, "Thin Lines");
            if (r.TryGetProperty("split", out var sp)) line(sp.GetDouble(), y0, sp.GetDouble(), r.GetProperty("y1").GetDouble(), "Thin Lines");
        }

        // text types, one per style (TEXT_SIZE is a TYPE parameter and is the CAP height). A semibold face is its
        // own font family ("Segoe UI Semibold") with bold OFF: Revit's bold flag would synthesise a 700.
        var baseType = new FilteredElementCollector(f).OfClass(typeof(TextNoteType)).Cast<TextNoteType>().FirstOrDefault();
        if (baseType == null) throw new InvalidOperationException("no TextNoteType in the family template");
        foreach (var p in L.GetProperty("styles").EnumerateObject()) {
            var s = p.Value;
            string tn = prefix + p.Name;
            var nt = new FilteredElementCollector(f).OfClass(typeof(TextNoteType)).Cast<TextNoteType>().FirstOrDefault(x => x.Name == tn)
                     ?? baseType.Duplicate(tn) as TextNoteType;
            nt.get_Parameter(BuiltInParameter.TEXT_FONT).Set(s.GetProperty("font").GetString());
            nt.get_Parameter(BuiltInParameter.TEXT_SIZE).Set(FT(s.GetProperty("pt").GetDouble() * s.GetProperty("cap").GetDouble() / 72.0));
            nt.get_Parameter(BuiltInParameter.TEXT_STYLE_BOLD).Set(s.GetProperty("bold").GetBoolean() ? 1 : 0);
            var c = s.GetProperty("rgb");
            nt.get_Parameter(BuiltInParameter.LINE_COLOR).Set(c[0].GetInt32() + c[1].GetInt32() * 256 + c[2].GetInt32() * 65536);
            try { nt.get_Parameter(BuiltInParameter.TEXT_BACKGROUND).Set(1); } catch { }   // transparent
            styleIds[p.Name] = nt.Id;
        }

        Action<double, double, double, string, string> put = (x, yTop, width, text, style) => {
            var o = new TextNoteOptions(styleIds[style]) { HorizontalAlignment = HorizontalTextAlignment.Left };
            TextNote.Create(f, view.Id, new XYZ(FT(x), FT(yTop), 0), FT(width), text, o);
            texts++;
        };
        double colW = x1 - x0 - 2 * pad;

        // field labels at the top of each row
        foreach (var r in rows.Values) {
            double y1 = r.GetProperty("y1").GetDouble();
            if (r.TryGetProperty("label", out var lab)) {
                double w = r.TryGetProperty("split", out var sp0) ? sp0.GetDouble() - x0 - 2 * pad : colW;
                put(x0 + pad, y1 - 0.12, w, lab.GetString(), "label");
            }
            if (r.TryGetProperty("label2", out var lab2)) {
                double sp = r.GetProperty("split").GetDouble();
                put(sp + pad, y1 - 0.12, x1 - sp - 2 * pad, lab2.GetString(), "label");
            }
        }
        // static words: wordmark, URL, tagline, disclaimer (already filled in for the property)
        foreach (var s in L.GetProperty("static").EnumerateArray()) {
            var r = rows[s.GetProperty("row").GetString()];
            put(x0 + pad, r.GetProperty("y1").GetDouble() - s.GetProperty("dy").GetDouble(), colW,
                s.GetProperty("text").GetString(), s.GetProperty("style").GetString());
        }
        t.Commit();
    }
    f.SaveAs(rfa, new SaveAsOptions { OverwriteExistingFile = true });
    f.Close(false);
} catch (Exception ex) {
    err = ex.GetType().Name + ": " + ex.Message;
    try { if (f != null) f.Close(false); } catch { }
}
if (err != null) return new { ok = false, stage = "author", error = err };
return new { ok = true, family = rfa, curves, texts, styles = styleIds.Keys.ToList(), sheet_in = W + " x " + H };
